import sys
data = sys.stdin.buffer.read()
try:
    s = data.decode('utf-8')
except UnicodeDecodeError:
    s = data.decode('utf-8', 'replace')
lines = s.split('\n')
trailing = True
if lines and lines[-1]=='':
    lines = lines[:-1]
else:
    trailing = False
for i,l in enumerate(lines):
    l2 = l.replace('\x1b','<ESC>').replace('\t','<TAB>').replace('\r','<CR>')
    print('%3d|%s|' % (i+1, l2))
if not trailing:
    print('    [NO TRAILING NEWLINE]')
if not lines:
    print('    [EMPTY OUTPUT %d bytes]' % len(data))
EOF
